CREATE TABLE IF NOT EXISTS deploy_dns_zone (
    id              BIGINT       NOT NULL,
    uuid            VARCHAR(36)  NOT NULL,
    tenant_id       BIGINT       NOT NULL,
    organization_id BIGINT       NOT NULL DEFAULT 0,
    apex_hostname   VARCHAR(253) NOT NULL,
    display_name    VARCHAR(200),
    dns_provider    VARCHAR(64),
    provider_zone_ref VARCHAR(512),
    status          VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    created_by      BIGINT,
    updated_by      BIGINT,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version         BIGINT       NOT NULL DEFAULT 1,
    deleted_at      TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_deploy_dns_zone_uuid UNIQUE (uuid),
    CONSTRAINT chk_deploy_dns_zone_status CHECK (status IN ('ACTIVE', 'PAUSED'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_deploy_dns_zone_active_apex
    ON deploy_dns_zone (apex_hostname)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_deploy_dns_zone_tenant_updated
    ON deploy_dns_zone (tenant_id, updated_at DESC, id DESC)
    WHERE deleted_at IS NULL;

-- source: migrations/002_create_deploy_domain.sql
-- Migration: 002_create_deploy_domain
-- Description: 创建域名绑定表
-- Author: SDKWork Deploy Server
-- Date: 2026-06-14

CREATE TABLE IF NOT EXISTS deploy_domain (
    id                  BIGINT       NOT NULL,
    uuid                VARCHAR(36)  NOT NULL,
    tenant_id           BIGINT       NOT NULL,
    organization_id     BIGINT       NOT NULL DEFAULT 0,
    zone_id             BIGINT       NOT NULL,
    hostname_ascii      VARCHAR(253) NOT NULL,
    hostname_type       VARCHAR(16)  NOT NULL DEFAULT 'EXACT',
    verification_status VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    verified_at         TIMESTAMPTZ,
    status              VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    metadata            JSONB        NOT NULL DEFAULT '{}',
    created_by          BIGINT,
    updated_by          BIGINT,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version             BIGINT       NOT NULL DEFAULT 1,
    deleted_at          TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_deploy_domain_uuid UNIQUE (uuid),
    CONSTRAINT fk_deploy_domain_zone FOREIGN KEY (zone_id) REFERENCES deploy_dns_zone(id),
    CONSTRAINT chk_deploy_domain_hostname_type CHECK (hostname_type IN ('EXACT', 'WILDCARD')),
    CONSTRAINT chk_deploy_domain_verification_status CHECK (verification_status IN ('PENDING', 'VERIFIED', 'FAILED', 'EXPIRED')),
    CONSTRAINT chk_deploy_domain_status CHECK (status IN ('ACTIVE', 'PAUSED')),
    CONSTRAINT chk_deploy_domain_verified_at CHECK (
        (verification_status = 'VERIFIED' AND verified_at IS NOT NULL)
        OR (verification_status <> 'VERIFIED' AND verified_at IS NULL)
    )
);

COMMENT ON TABLE deploy_domain IS 'DNS Zone 下可验证、可绑定的 hostname 资源；不直接拥有应用或 TLS 配置';
COMMENT ON COLUMN deploy_domain.hostname_ascii IS '经 IDNA 规范化的小写 ASCII hostname';
COMMENT ON COLUMN deploy_domain.hostname_type IS 'EXACT 或 WILDCARD';
COMMENT ON COLUMN deploy_domain.verification_status IS '所有权验证状态';
COMMENT ON COLUMN deploy_domain.status IS 'hostname 管理生命周期状态';

CREATE UNIQUE INDEX IF NOT EXISTS uk_deploy_domain_active_hostname
    ON deploy_domain (hostname_ascii)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_deploy_domain_tenant_status
    ON deploy_domain (tenant_id, status, updated_at DESC, id DESC)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_deploy_domain_zone_updated
    ON deploy_domain (tenant_id, zone_id, updated_at DESC, id DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS deploy_domain_verification (
    id                    BIGINT       NOT NULL,
    uuid                  VARCHAR(36)  NOT NULL,
    tenant_id             BIGINT       NOT NULL,
    domain_id             BIGINT       NOT NULL,
    method                VARCHAR(16)  NOT NULL,
    record_name           VARCHAR(253) NOT NULL,
    proof_sha256          VARCHAR(64)  NOT NULL,
    status                VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    observed_sha256       VARCHAR(64),
    verifier_identity     VARCHAR(128),
    attempt_count         INTEGER      NOT NULL DEFAULT 0,
    next_attempt_at       TIMESTAMPTZ,
    expires_at            TIMESTAMPTZ  NOT NULL,
    checked_at            TIMESTAMPTZ,
    verified_at           TIMESTAMPTZ,
    failure_code          VARCHAR(64),
    created_by            BIGINT,
    created_at            TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at            TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version               BIGINT       NOT NULL DEFAULT 1,
    PRIMARY KEY (id),
    CONSTRAINT uk_deploy_domain_verification_uuid UNIQUE (uuid),
    CONSTRAINT fk_deploy_domain_verification_domain FOREIGN KEY (domain_id) REFERENCES deploy_domain(id),
    CONSTRAINT chk_deploy_domain_verification_method CHECK (method IN ('DNS_TXT', 'DNS_CNAME', 'HTTP_FILE')),
    CONSTRAINT chk_deploy_domain_verification_status CHECK (status IN ('PENDING', 'CHECKING', 'VERIFIED', 'FAILED', 'EXPIRED')),
    CONSTRAINT chk_deploy_domain_verification_hash CHECK (
        proof_sha256 ~ '^[0-9a-f]{64}$'
        AND (observed_sha256 IS NULL OR observed_sha256 ~ '^[0-9a-f]{64}$')
    ),
    CONSTRAINT chk_deploy_domain_verification_attempts CHECK (attempt_count BETWEEN 0 AND 1000)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_deploy_domain_verification_active
    ON deploy_domain_verification (domain_id)
    WHERE status IN ('PENDING', 'CHECKING');

CREATE INDEX IF NOT EXISTS idx_deploy_domain_verification_due
    ON deploy_domain_verification (status, next_attempt_at, expires_at, id)
    WHERE status IN ('PENDING', 'CHECKING');

