-- source: migrations/004_create_deploy_certificate.sql
-- Migration: 004_create_deploy_certificate
-- Description: 创建 SSL 证书表
-- Author: SDKWork Deploy Server
-- Date: 2026-06-14

CREATE TABLE IF NOT EXISTS deploy_certificate (
    id                      BIGINT       NOT NULL,
    uuid                    VARCHAR(36)  NOT NULL,
    tenant_id               BIGINT       NOT NULL,
    organization_id         BIGINT       NOT NULL DEFAULT 0,
    cert_name               VARCHAR(200) NOT NULL,
    certificate_source      VARCHAR(16)  NOT NULL DEFAULT 'MANAGED',
    ca_profile              VARCHAR(32)  NOT NULL DEFAULT 'LETS_ENCRYPT_PRODUCTION',
    preferred_key_algorithm VARCHAR(16)  NOT NULL DEFAULT 'ECDSA',
    auto_renew              BOOLEAN      NOT NULL DEFAULT TRUE,
    renewal_status          VARCHAR(16)  NOT NULL DEFAULT 'NONE',
    status                  VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    idempotency_key         VARCHAR(128) NOT NULL,
    request_sha256          VARCHAR(64)  NOT NULL,
    metadata                JSONB        NOT NULL DEFAULT '{}',
    created_by              BIGINT,
    updated_by              BIGINT,
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version                 BIGINT       NOT NULL DEFAULT 1,
    deleted_at              TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_deploy_certificate_uuid UNIQUE (uuid),
    CONSTRAINT uk_deploy_certificate_idempotency UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT chk_deploy_certificate_source CHECK (certificate_source IN ('MANAGED', 'CUSTOM')),
    CONSTRAINT chk_deploy_certificate_ca_profile CHECK (ca_profile IN ('LETS_ENCRYPT_STAGING', 'LETS_ENCRYPT_PRODUCTION', 'CUSTOM')),
    CONSTRAINT chk_deploy_certificate_key_algorithm CHECK (preferred_key_algorithm IN ('RSA', 'ECDSA')),
    CONSTRAINT chk_deploy_certificate_renewal_status CHECK (renewal_status IN ('NONE', 'PLANNED', 'PROCESSING', 'FAILED')),
    CONSTRAINT chk_deploy_certificate_status CHECK (status IN ('PENDING', 'ISSUING', 'ACTIVE', 'EXPIRED', 'FAILED', 'REVOKED')),
    CONSTRAINT chk_deploy_certificate_request_hash CHECK (request_sha256 ~ '^[0-9a-f]{64}$')
);

COMMENT ON TABLE deploy_certificate IS 'TLS certificate lifecycle aggregate; hostname identifiers and immutable material versions are stored separately';
COMMENT ON COLUMN deploy_certificate.certificate_source IS 'MANAGED ACME lifecycle or CUSTOM secret-manager lifecycle';
COMMENT ON COLUMN deploy_certificate.preferred_key_algorithm IS 'Preferred issuance key algorithm; active RSA and ECDSA versions may coexist';

CREATE INDEX IF NOT EXISTS idx_deploy_certificate_renewal
    ON deploy_certificate (tenant_id, renewal_status, updated_at, id)
    WHERE auto_renew = TRUE AND status IN ('ACTIVE', 'FAILED') AND deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_deploy_certificate_tenant_updated
    ON deploy_certificate (tenant_id, updated_at DESC, id DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS deploy_certificate_identifier (
    id              BIGINT       NOT NULL,
    uuid            VARCHAR(36)  NOT NULL,
    tenant_id       BIGINT       NOT NULL,
    certificate_id  BIGINT       NOT NULL,
    domain_id       BIGINT       NOT NULL,
    identifier_type VARCHAR(16)  NOT NULL,
    hostname_ascii  VARCHAR(253) NOT NULL,
    position        INTEGER      NOT NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    CONSTRAINT uk_deploy_certificate_identifier_uuid UNIQUE (uuid),
    CONSTRAINT uk_deploy_certificate_identifier_name UNIQUE (certificate_id, hostname_ascii),
    CONSTRAINT uk_deploy_certificate_identifier_position UNIQUE (certificate_id, position),
    CONSTRAINT fk_deploy_certificate_identifier_certificate FOREIGN KEY (certificate_id) REFERENCES deploy_certificate(id),
    CONSTRAINT fk_deploy_certificate_identifier_domain FOREIGN KEY (domain_id) REFERENCES deploy_domain(id),
    CONSTRAINT chk_deploy_certificate_identifier_type CHECK (identifier_type IN ('EXACT', 'WILDCARD')),
    CONSTRAINT chk_deploy_certificate_identifier_position CHECK (position BETWEEN 0 AND 99)
);

CREATE INDEX IF NOT EXISTS idx_deploy_certificate_identifier_domain
    ON deploy_certificate_identifier (tenant_id, domain_id, certificate_id);

CREATE TABLE IF NOT EXISTS deploy_certificate_version (
    id                BIGINT       NOT NULL,
    uuid              VARCHAR(36)  NOT NULL,
    tenant_id         BIGINT       NOT NULL,
    certificate_id    BIGINT       NOT NULL,
    version_no        BIGINT       NOT NULL,
    serial_sha256     VARCHAR(64)  NOT NULL,
    fingerprint_sha256 VARCHAR(64) NOT NULL,
    spki_sha256       VARCHAR(64)  NOT NULL,
    chain_sha256      VARCHAR(64)  NOT NULL,
    issuer            VARCHAR(500) NOT NULL,
    subject           VARCHAR(500) NOT NULL,
    key_algorithm     VARCHAR(16)  NOT NULL,
    not_before        TIMESTAMPTZ  NOT NULL,
    not_after         TIMESTAMPTZ  NOT NULL,
    secret_bundle_ref VARCHAR(1024) NOT NULL,
    source_order_id   BIGINT,
    status            VARCHAR(16)  NOT NULL DEFAULT 'CANDIDATE',
    created_by        BIGINT,
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    CONSTRAINT uk_deploy_certificate_version_uuid UNIQUE (uuid),
    CONSTRAINT uk_deploy_certificate_version_no UNIQUE (certificate_id, version_no),
    CONSTRAINT uk_deploy_certificate_version_fingerprint UNIQUE (tenant_id, fingerprint_sha256),
    CONSTRAINT fk_deploy_certificate_version_certificate FOREIGN KEY (certificate_id) REFERENCES deploy_certificate(id),
    CONSTRAINT chk_deploy_certificate_version_key_algorithm CHECK (key_algorithm IN ('RSA', 'ECDSA')),
    CONSTRAINT chk_deploy_certificate_version_status CHECK (status IN ('CANDIDATE', 'ACTIVE', 'SUPERSEDED', 'REVOKED', 'EXPIRED')),
    CONSTRAINT chk_deploy_certificate_version_validity CHECK (not_after > not_before),
    CONSTRAINT chk_deploy_certificate_version_hashes CHECK (
        serial_sha256 ~ '^[0-9a-f]{64}$'
        AND fingerprint_sha256 ~ '^[0-9a-f]{64}$'
        AND spki_sha256 ~ '^[0-9a-f]{64}$'
        AND chain_sha256 ~ '^[0-9a-f]{64}$'
    ),
    CONSTRAINT chk_deploy_certificate_version_secret_ref CHECK (
        secret_bundle_ref LIKE 'secret://%' OR secret_bundle_ref LIKE 'file:%'
    )
);

CREATE INDEX IF NOT EXISTS idx_deploy_certificate_version_lifecycle
    ON deploy_certificate_version (tenant_id, status, not_after, id);

ALTER TABLE deploy_certificate
    ADD COLUMN IF NOT EXISTS desired_version_id BIGINT,
    ADD COLUMN IF NOT EXISTS current_version_id BIGINT;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_deploy_certificate_desired_version') THEN
        ALTER TABLE deploy_certificate ADD CONSTRAINT fk_deploy_certificate_desired_version FOREIGN KEY (desired_version_id) REFERENCES deploy_certificate_version(id);
    END IF;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_deploy_certificate_current_version') THEN
        ALTER TABLE deploy_certificate ADD CONSTRAINT fk_deploy_certificate_current_version FOREIGN KEY (current_version_id) REFERENCES deploy_certificate_version(id);
    END IF;
END $$;

