    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT pk_deploy_usage_event PRIMARY KEY (id),
    CONSTRAINT fk_deploy_usage_event_app
        FOREIGN KEY (app_id) REFERENCES deploy_app(id),
